// Generated by bildr from .bildr/datasources/weather.json. Editing this file detaches it from the editor.
import { describe, expect, it } from 'vitest'
import { fromForecast, toForecast } from '../../shared/infrastructure/weather/mappers/forecast.mapper'

describe('the mappers of the "weather" API', () => {
  it('Forecast: maps to the domain (every field has a value)', () => {
    expect(toForecast({
      city: 'city 1',
      celsius: 1.5,
      observed_at: '2024-01-02T03:04:05.000Z'
    })).toEqual({
      city: 'city 1',
      celsius: 1.5,
      observedAt: '2024-01-02T03:04:05.000Z'
    })
  })

  it('Forecast: goes back to what the API sent (every field has a value)', () => {
    expect(fromForecast(toForecast({
      city: 'city 1',
      celsius: 1.5,
      observed_at: '2024-01-02T03:04:05.000Z'
    }))).toEqual({
      city: 'city 1',
      celsius: 1.5,
      observed_at: '2024-01-02T03:04:05.000Z'
    })
  })
})
